#!/usr/bin/env node
// Red controls: prove each gate can fail. For every control, copy the product
// tree to a temporary directory, apply one deliberate defect to the source, run
// the tests that guard it, and require a NON-zero exit. A baseline run of the
// unmodified copy must exit zero first. Output: JSON results on stdout.
import { spawn, spawnSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { cp, mkdtemp, readFile, rm, symlink, writeFile } from 'node:fs/promises';
import { existsSync, readdirSync, readFileSync, realpathSync } from 'node:fs';
import { createHash, randomBytes } from 'node:crypto';
import { availableParallelism, loadavg, tmpdir } from 'node:os';
import { basename, dirname, join, resolve } from 'node:path';

// fileURLToPath, not URL.pathname: pathname keeps percent-encoding (a space
// becomes %20), which broke --check in checkouts whose path contains a space.
const REPO = resolve(fileURLToPath(new URL('..', import.meta.url)));
// Scripts that do nothing on import (their CLI is guarded), so a mutation of them can
// be load-checked like a library module. Other scripts act on import: parse-check only.
// V2.1 operator scripts guard their CLI and act only when run live, so they load safely too.
const LOAD_SAFE_SCRIPTS = new Set(['scripts/red-controls.mjs', 'scripts/compare-engines.mjs', 'scripts/hcl-scan.mjs', 'scripts/scope-mentions.mjs', 'scripts/scope-tables.mjs', 'scripts/lib/cf-api.mjs', 'scripts/cf-preflight.mjs', 'scripts/cf-token-verify.mjs', 'scripts/d1-schema.mjs', 'scripts/secret-gate.mjs', 'scripts/cf-capture.mjs', 'scripts/evidence-packet.mjs', 'scripts/cf-receipts.mjs', 'scripts/cf-absence.mjs']);

