// Every file in a scratch copy right after it is prepared, with its SHA-256
// (node_modules is a symlink and is not walked). A copy is intact while every one of these
// files still exists with the same content: tests may add files, but nothing may remove,
// modify or truncate the copy's own (V2-QA-6). The harness's own mutation is the one
// expected change, and updates its file's hash.
const sha256 = (buf) => createHash('sha256').update(buf).digest('hex');
function inventory(dir, rel = '', out = new Map()) {
  for (const e of readdirSync(join(dir, rel), { withFileTypes: true })) {
    const p = rel ? `${rel}/${e.name}` : e.name;
    if (p === 'node_modules') continue;
    if (e.isDirectory()) inventory(dir, p, out);
    else out.set(p, sha256(readFileSync(join(dir, p))));
  }
  return out;
}
function changesFrom(dir, files) {
  if (!existsSync(dir)) return { missing: files.size, modified: 0, example: '(the whole copy)' };
  const missing = [];
  const modified = [];
  for (const [f, h] of files) {
    let buf;
    try {
      buf = readFileSync(join(dir, f));
    } catch {
      missing.push(f);
      continue;
    }
    if (sha256(buf) !== h) modified.push(f);
  }
  return missing.length || modified.length ? { missing: missing.length, modified: modified.length, example: missing[0] ?? modified[0] } : null;
}

// The top-level entries a control's scratch copy holds: the product tree, the control's extras, and, for a control
// that needs the docs, the root Markdown files (README.md and the rest), which the scope-name gate reads alongside
// docs/** (V2-QA-6). One definition, under one name: prepare() copies exactly these, and two tests derive from it
// that each control's copy holds what its tests read. They check different things and neither covers the other:
// test/unit/red-controls-copy-set.test.mjs, for every control, the top-level entries its tests name as path literals;
// test/unit/red-controls-copy-scope.test.mjs, the paths two tests take from data (the README's links, every control's file).
export const COPY_ALWAYS = ['src', 'test', 'fixtures', 'scripts', 'package.json'];
export function copyEntries(extra = []) {
  const roots = extra.includes('docs') ? readdirSync(REPO).filter((f) => /\.md$/i.test(f)) : [];
  return [...new Set([...COPY_ALWAYS, ...extra, ...roots])];
}

async function prepare(extra = []) {
  const dir = await mkdtemp(join(tmpdir(), 'canon-red-'));
  for (const entry of copyEntries(extra)) await cp(join(REPO, entry), join(dir, entry), { recursive: true });
  await symlink(join(REPO, 'node_modules'), join(dir, 'node_modules'));
  return dir;
}

// The names of the failing tests in TAP output. TAP escapes `\` and `#` in a test's description
// (`PKCS\#8`); they are unescaped here, so an intended test whose name holds `#` still matches.
export function tapFailures(out) {
  return [...out.matchAll(/^not ok \d+ - (.*)$/gm)].map((m) => m[1].replace(/\\([\\#])/g, '$1'));
}

// WHOSE PROCESS IS IT (host safety, 2026-10-05). A process is stopped by this harness only when the
// harness can PROVE it started it. A pid or a process-group number alone proves nothing: the system
// hands the number to a stranger as soon as its last process is gone. On 2026-10-05 a run-end sweep
// matched remembered group numbers and stopped 19 processes of other projects. The two proofs:
//   HELD GROUP  every test run is started under a holder, a shell this harness spawns as the leader
//               of a new session and keeps alive on a pipe. While the holder lives its number cannot
//               be reused and only its own session can be in its group, so every member is ours.
//               The group is listed and its leftovers stopped THEN; only after that is the holder
//               released, and its number is never matched again.
//   RUN TOKEN   each control's test runs carry a fresh random token in their environment. A process
//               whose environment holds that exact token was started by one of those runs, wherever
//               it went (a server that left the session). Other processes' environments are read
//               only to test for the token: nothing of them is kept, logged or written anywhere, and
//               the token itself is never written to a result. (macOS shows no environment for its
//               own platform binaries, such as /bin/sh and /bin/sleep: those are proven by the group
//               only.)
// Every signal goes to a pid AND its start time, read again immediately before SIGTERM and again
// before SIGKILL: a pid whose start time changed is someone else and is left alone.
// A process found only by a PATH (its command line or working directory names this run's copy) is
// not proven ours: it is reported with its pid and start time and counted against that control, and
// it is never signalled.
// Start times are compared as text, so every ps runs in one fixed locale and time zone.
