function runTests(dir, tests, only = null, token = null) {
  const limitMs = testTimeoutMs();
  // Red controls always run loopback-only: live tailnet tests stay skipped and any
  // non-loopback bind attempt fails (CANON_LOOPBACK_ONLY=1, CANON_LIVE_TAILNET unset).
  const env = { ...process.env, CANON_EVIDENCE_DIR: '', CANON_LOOPBACK_ONLY: '1' };
  delete env.CANON_LIVE_TAILNET;
  // Run as a top-level test run even when the harness itself runs under `node --test`:
  // an inherited NODE_TEST_CONTEXT makes the child print no TAP and exit 0 even when its
  // tests fail, so every control would silently read "not red".
  delete env.NODE_TEST_CONTEXT;
  // Always this run's own token, never one inherited from a harness that runs this one as a test.
  delete env[RUN_TOKEN_NAME];
  if (token) env[RUN_TOKEN_NAME] = token;
  // The TAP reporter is named explicitly: Node 26 defaults to the spec reporter even
  // when piped, and the failed-test list below parses TAP. Without it, every control's
  // `failed` list came back empty (exit codes still held).
  return new Promise((resolveRun, rejectRun) => {
    const child = spawn('/bin/sh', ['-c', HOLDER, 'canon-red-holder', process.execPath, '--test', '--test-reporter=tap', '--test-concurrency=1', ...(only ?? []).map((name) => `--test-name-pattern=${exactName(name)}`), ...tests], { cwd: dir, env, detached: true, stdio: ['ignore', 'pipe', 'pipe', 'pipe', 'pipe'] });
    const holder = { pid: child.pid, start: null, reader: null };
    if (child.pid) holder.start = startOf(child.pid);
    const toHolder = child.stdio[4];
    // A holder that is gone closes its pipe: writing to it must not crash the harness.
    toHolder?.on('error', () => {});
    let released = false;
    const tell = (word) => { try { if (toHolder?.writable) toHolder.write(`${word}\n`); } catch { /* the holder is gone */ } };
    const end = () => { released = true; tell('kill'); try { toHolder?.end(); } catch { /* the holder is gone */ } };
    LIVE_HOLDERS.add(end);
    let stdout = '';
    let stderr = '';
    let fromHolder = '';
    let status = null;
    let timedOut = false;
    let lost = false;
    let left = [];
    let exiting = [];
    let settled = false;
    child.stdout.setEncoding('utf8').on('data', (d) => { stdout += d; });
    child.stderr.setEncoding('utf8').on('data', (d) => { stderr += d; });
    const limit = setTimeout(() => { timedOut = true; end(); }, limitMs);
    // The test has ended and the holder still holds the group: list it, let the holder stop what
    // is left, then release the holder.
    const afterTest = async () => {
      let members = heldGroupMembers(holder);
      if (members === null) { lost = true; end(); return; }
      left = members;
      if (members.length) {
        tell('term');
        for (let waited = 0; waited < GRACE_MS && members?.length; waited += 100) {
          await new Promise((r) => setTimeout(r, 100));
          members = heldGroupMembers(holder);
        }
        if (members === null) lost = true;
      }
      // What is on its way out is given the same grace and then written down, not counted.
      for (let waited = 0; waited < GRACE_MS && (exiting = heldGroupExiting(holder) ?? []).length; waited += 100) await new Promise((r) => setTimeout(r, 100));
      end();
    };
    child.stdio[3].setEncoding('utf8').on('data', (d) => {
      fromHolder += d;
      const reader = fromHolder.match(/^reader (\d+)$/m);
      if (reader && holder.reader === null) holder.reader = Number(reader[1]);
      const said = fromHolder.match(/^status (\d+)$/m);
      if (said && status === null) { status = Number(said[1]); afterTest(); }
    });
    const finish = () => {
      if (settled) return;
      settled = true;
      clearTimeout(limit);
      LIVE_HOLDERS.delete(end);
      // A process that left the group may hold the output pipes open for as long as it lives:
      // nothing more is read from them, and they must not keep the harness waiting.
      for (const stream of [child.stdout, child.stderr, child.stdio[3]]) stream?.destroy();
      if (timedOut) { rejectRun(Object.assign(new Error(`a test run of ${JSON.stringify(tests)} was stopped after ${limitMs / 1000} s`), { code: 'ETESTTIMEOUT' })); return; }
      // The holder went before the harness released it (a test that ends its own group, a crash):
      // the group is unknown from then on.
      if (lost || status === null || !released) { end(); rejectRun(Object.assign(new Error(`the holder of a test run of ${JSON.stringify(tests)} was gone before it was released: its process group is unknown, and nothing was listed or signalled by its number`), { code: 'EHOLDERLOST' })); return; }
      const out = `${stdout}${stderr}`;
      // Every failing test, so a control can be checked to fail at its intended assertion.
      const failed = tapFailures(out);
      const failedWhy = tapFailureMessages(out);
      resolveRun({ exitCode: status, pass: Number(out.match(/^# pass (\d+)/m)?.[1] ?? NaN), fail: Number(out.match(/^# fail (\d+)/m)?.[1] ?? NaN), firstFailure: failed[0] ?? null, failed, failedWhy, ...(only ? { ran: selectedTests(tapTests(out), tests) } : {}), swept: { left, exiting } });
    };
    child.on('error', (err) => { clearTimeout(limit); LIVE_HOLDERS.delete(end); if (!settled) { settled = true; rejectRun(err); } });
    // 'close' waits for the output pipes, which a process that left the group may keep open: the
    // time limit ends at the holder's exit, and the result is taken shortly after it at the latest.
    child.on('exit', () => { clearTimeout(limit); setTimeout(finish, 1000).unref(); });
    child.on('close', finish);
  });
}

// The number of controls a full run must find. A control added or lost without
// updating this fails the run instead of silently changing what "all red" means.
export const EXPECTED_CONTROL_COUNT = 588;

export class ControlSelectionError extends Error {
  constructor(message, details) {
    super(message);
    this.name = 'ControlSelectionError';
    this.details = details;
  }
}

// A full control set: the expected count, and every ID unique.
export function assertFullSet(controls, expected = EXPECTED_CONTROL_COUNT) {
  const ids = controls.map((c) => c.id);
  const duplicates = [...new Set(ids.filter((id, i) => ids.indexOf(id) !== i))];
  if (controls.length !== expected || duplicates.length) {
    throw new ControlSelectionError(`control set has ${controls.length} controls, expected ${expected}${duplicates.length ? `; duplicate IDs: ${duplicates.join(', ')}` : ''}`, { count: controls.length, expected, duplicates });
  }
}

// Every control names its defect by a find text, which must occur exactly once in its file. With
// none the control cannot be applied. With two, the first is changed, which need not be the line
// the control was written for: its baseline passes and the control quietly stops going red.
export function anchorProblems(controls = CONTROLS, read = (path) => readFileSync(join(REPO, path), 'utf8')) {
  const problems = [];
  for (const c of controls) {
    let count;
    try { count = read(c.file).split(c.find).length - 1; } catch { count = -1; }
    if (count !== 1) problems.push(`${c.id}: its find occurs ${count < 0 ? 'nowhere (file missing)' : `${count} times`} in ${c.file}`);
  }
  return problems;
}

// A run refuses its whole selection, before any copy is made, if any selected control fails that
// rule, and names each one (AP.8 integration item I-2).
export function assertAnchored(controls) {
  const problems = anchorProblems(controls);
  if (problems.length) throw new ControlSelectionError(`${problems.length} selected control${problems.length > 1 ? 's' : ''} cannot be applied as written: ${problems.join('; ')}`, { unanchored: problems });
}

// Which controls a run covers. No IDs means every control, checked against the
// expected count. Named IDs must each match a control exactly: an unknown or
// mistyped ID fails the whole selection, naming every unmatched ID, before anything
// runs. A selection that matches nothing is a failure, never an empty success.
export function selectControls(ids = [], controls = CONTROLS) {
  if (!ids.length) {
    assertFullSet(controls);
    return controls;
  }
  const known = new Set(controls.map((c) => c.id));
  const unmatched = [...new Set(ids)].filter((id) => !known.has(id));
  if (unmatched.length) throw new ControlSelectionError(`unmatched control ID${unmatched.length > 1 ? 's' : ''}: ${unmatched.map((id) => JSON.stringify(id)).join(', ')}`, { unmatched });
  const selected = controls.filter((c) => ids.includes(c.id));
  if (!selected.length) throw new ControlSelectionError('no control matched', { unmatched: [] });
  return selected;
}

// Each control's result is recorded before its scratch copy is cleaned up, and a control
// whose run fails (for example because its copy vanished) is recorded as not red with
// the reason: one bad control never discards the others' results. Cleanup tolerates a
// missing copy and records a warning in that control's result. `controls` and
// `afterPrepare` are for tests only.
// A run passes only if every selected control has a result, every result is red, and no
// control's scratch copy vanished or left a warning at any phase. A copy that vanishes
// mid-run makes its tests fail for the wrong reason, which must never count as red.
// Likewise a control is red only at its intended assertion: each control names, in
// `intends`, the test(s) whose failure demonstrates its defect. The mutated run executes
// exactly those tests (PERF-1), every one of them must have run, and every one must fail.
export function runVerdict(results, selectedCount = results.length) {
  const problems = [];
  if (results.length === 0 || results.length !== selectedCount) problems.push(`${results.length} results for ${selectedCount} selected controls`);
  // What fails the run as a whole (a group that became unknown, a process no control owns).
  for (const p of results.runProblems ?? []) problems.push(`run: ${p}`);
  for (const r of results) {
    if (r.vanished) problems.push(`${r.id}: scratch copy vanished during ${r.vanished.phase}`);
    if (r.warnings?.length) problems.push(`${r.id}: ${r.warnings.length} warning(s)`);
    if (r.modified) problems.push(`${r.id}: scratch copy modified during ${r.modified.phase}`);
    if (r.error) problems.push(`${r.id}: ${r.error}`);
    if (r.leftBehind?.baseline) problems.push(`${r.id}: the unmutated tests left ${r.leftBehind.baseline} process(es) running`);
    if (r.strays?.length) problems.push(`${r.id}: ${r.strays.length} stray process(es) outlived the control`);
    // A stray found by a path alone is not proven to be this run's: it was reported and NOT stopped.
    for (const p of (r.strays ?? []).filter((x) => x.signalled === false)) problems.push(`${r.id}: a process found by path only was NOT stopped (pid ${p.pid}, started ${p.start ?? 'unknown'}): ${p.why ?? 'not proven to be this run\'s'}`);
    if (r.sweepIncomplete) problems.push(`${r.id}: the run-end sweep for stray processes did not complete (${r.sweepIncomplete})`);
    if (r.reusedFromStrayOwner) problems.push(`${r.id}: reused an unmutated run of ${r.reusedFromStrayOwner}, which left a stray process`);
    if (r.alone && r.intendedAlone === false) problems.push(`${r.id}: its intended tests do not pass alone on the unmutated copy (ran ${JSON.stringify(r.alone.ran ?? [])}, failed ${JSON.stringify(r.alone.failed ?? [])})`);
    if (r.broken && r.broken.exitCode !== 0 && !r.intendedFailed?.length) problems.push(`${r.id}: failed, but not at its intended assertion`);
    // A red baseline makes any later "red" meaningless (H-QA-2): say so by name.
    if (r.baseline && r.baseline.exitCode !== 0) problems.push(`${r.id}: baseline is not green (exit ${r.baseline.exitCode}, first failure: ${r.baseline.firstFailure ?? 'none named'}); its copy may lack a file its tests read`);
    if (r.broken && r.ranIntended === false) problems.push(`${r.id}: the mutated run did not run exactly its intended tests (ran ${JSON.stringify(r.broken.ran ?? [])})`);
    if (r.broken && r.ranIntended && r.intendedFailed.length !== r.intends.length) problems.push(`${r.id}: ${r.intends.length - r.intendedFailed.length} intended test(s) did not fail`);
    if (!r.wentRed) problems.push(`${r.id}: not red`);
  }
  return { ok: problems.length === 0, problems };
}

// Each control's result is recorded before its scratch copy is cleaned up, and a control
// whose run fails is recorded as not red with the reason: one bad control never discards
// the others' results. The copy is checked against its prepared inventory after the
// baseline, after the mutation is applied, after the mutated run and before cleanup; if
// any of its files are gone at any phase (or cleanup warns), the control is NOT red.
// `controls`, `afterPrepare` and `beforeCleanup` are for tests only.
export async function runControls(ids, { controls = CONTROLS, afterPrepare = null, beforeCleanup = null, jobs = undefined, reuseBaselines = true } = {}) {
  const results = [];
  const size = poolSize(jobs);
  // Green, clean baselines of this run by key, in memory only: nothing is kept between runs.
  const baselines = new Map();
  // The same for the unmutated run of a control's intended tests alone, by baseline key and names.
  const alones = new Map();
  // A bad time limit is refused before anything runs.
  testTimeoutMs();
  const unhook = ['SIGINT', 'SIGTERM'].map(stopGroupsOn);
  // What was already running when this run began: the run-end sweep looks only at what is newer.
  const before = processSnapshot();
  // Every control's scratch copies and run token, for the run-end sweep. No process-group number is kept.
  const owned = [];
  // What fails the RUN as a whole, whatever each control says: a group that became unknown, a
  // process that names a copy no control owns.
  const runProblems = [];
  const selected = selectControls(ids ?? [], controls);
  assertAnchored(selected);
  const runOne = async (control, index) => {
    // Where each control's wall time goes, in milliseconds per phase (PERF-1). Reported only: no
    // verdict reads it.
    const timings = {};
    let mark = performance.now();
    const lap = (phase) => { const now = performance.now(); timings[phase] = Math.round((timings[phase] ?? 0) + now - mark); mark = now; };
    const dir = await prepare(control.extra);
    lap('copy');
    const files = inventory(dir);
    lap('inventory');
    const warnings = [];
    // The token of this control's test runs: fresh, random, never written to a result.
    const mine = { id: control.id, dirs: [...new Set([dir, realpathSync(dir)])], token: randomBytes(16).toString('hex'), before: processSnapshot(), swept: null };
    owned.push(mine);
    const left = { baseline: 0, mutated: 0 };
    let strays = [];
    // Members of a held group still on their way out after the grace: reported, never counted.
    const exitingNotCounted = [];
    // What a test run left alive. In its held group: already stopped from inside by the holder
    // (`swept`). Outside it: stopped only when PROVEN this control's (its token, in its copy);
    // anything found by a path alone is counted and reported as a stray that was NOT stopped.
    const sweep = async (phase, swept = null) => {
      const inGroup = swept?.left ?? [];
      for (const p of swept?.exiting ?? []) exitingNotCounted.push({ ...p, phase });
      const outside = leftOutside({ token: mine.token, dirs: mine.dirs, before: mine.before });
      left[phase] += inGroup.length + outside.proven.length + outside.reported.length;
      if (outside.proven.length) strays = [...strays, ...(await reap(outside.proven, mine.token)).map((p) => ({ ...p, phase, stopped: false }))];
      for (const p of outside.reported) if (!strays.some((x) => x.pid === p.pid && x.start === p.start)) strays.push({ ...p, phase, signalled: false, stopped: false });
    };
    const base = { id: control.id, rows: control.rows, defect: control.defect, file: control.file, tests: control.tests, intends: control.intends ?? [], note: control.note ?? null };
    let result = null;
    let vanished = null;
    let modified = null;
    const check = (phase) => {
      const change = changesFrom(dir, files);
      if (!change) return;
      if (change.missing && !vanished) {
        vanished = { phase, missingFiles: change.missing, example: change.example };
        warnings.push(`scratch copy ${dir} lost ${change.missing} file(s) (e.g. ${change.example}) during ${phase}`);
      }
      if (change.modified && !modified) {
        modified = { phase, modifiedFiles: change.modified };
        warnings.push(`scratch copy ${dir} had ${change.modified} file(s) modified or truncated during ${phase}`);
      }
    };
    try {
      if (afterPrepare) await afterPrepare(dir, control);
      check('prepare');
      lap('check');
      // The baseline: reused when an identical copy already ran the same tests green and clean in
      // this run, otherwise run here. A copy that changed during prepare is never keyed.
      const key = reuseBaselines && !vanished && !modified ? baselineKey(control.tests, inventory(dir)) : null;
      lap('inventory');
      const earlier = key ? await baselines.get(key) : null;
      lap('baselineWait');
      let baseline;
      let reusedFrom = null;
      if (earlier) {
        ({ baseline, id: reusedFrom } = earlier);
      } else {
        let settle = () => {};
        if (key) baselines.set(key, new Promise((r) => { settle = r; }));
        try {
          const { swept, ...ran } = await runTests(dir, control.tests, null, mine.token);
          baseline = ran;
          await sweep('baseline', swept);
          lap('baseline');
          check('baseline');
        } finally {
          // Only a green baseline that left nothing behind, in a copy still intact, is offered on.
          const offer = baseline && baseline.exitCode === 0 && !left.baseline && !strays.length && !vanished && !modified ? { baseline, id: control.id } : null;
          if (key && !offer) baselines.delete(key);
          settle(offer);
        }
      }
      lap('check');
      // The mutated run executes the intended tests alone, so they must first pass alone on the
      // UNMUTATED copy: a test that needs an earlier test of its file fails alone whatever the
      // mutation, and would read as red at intent. Exactly the intended tests must run, each once,
      // and all pass. Reused like the baseline, per identical copy and identical names.
      let alone = null;
      let aloneFrom = null;
      if (baseline.exitCode === 0 && base.intends.length && !vanished && !modified) {
        const aloneKey = key ? sha256(JSON.stringify([key, [...base.intends].sort()])) : null;
        const earlierAlone = aloneKey ? await alones.get(aloneKey) : null;
        lap('baselineWait');
        if (earlierAlone) {
          ({ alone, id: aloneFrom } = earlierAlone);
        } else {
          let settleAlone = () => {};
          if (aloneKey) alones.set(aloneKey, new Promise((r) => { settleAlone = r; }));
          const leftBefore = left.baseline;
          try {
            const { swept, ...ran } = await runTests(dir, control.tests, base.intends, mine.token);
            alone = ran;
            await sweep('baseline', swept); // this run is unmutated too: it must leave nothing
            lap('alone');
            check('intended tests alone');
          } finally {
            const offered = alone && alone.exitCode === 0 && left.baseline === leftBefore && !strays.length && !vanished && !modified ? { alone, id: control.id } : null;
            if (aloneKey && !offered) alones.delete(aloneKey);
            settleAlone(offered);
          }
        }
      }
      const intendedAlone = alone !== null && alone.exitCode === 0 && alone.failed.length === 0 && alone.ran.length === base.intends.length && [...alone.ran].sort().join('\n') === [...base.intends].sort().join('\n');
      lap('check');
      const path = join(dir, control.file);
      const original = await readFile(path, 'utf8');
      const applied = original.includes(control.find);
      // A function replacer inserts control.replace literally: a string replacement
      // expands "$&" and friends, which once turned R21/R22 into syntax errors that
      // "went red" without restoring their defects.
      if (applied) await writeFile(path, original.replace(control.find, () => control.replace));
      // The mutation is the one expected change to the copy.
      if (applied) files.set(control.file, sha256(await readFile(path)));
      // A control counts only if the mutated source still parses: a module that fails
      // to load turns every test red whatever the defect.
      const parses = !applied || !/\.m?js$/.test(control.file) || spawnSync(process.execPath, ['--check', path]).status === 0;
      // ...and only if it still loads: a module that parses but throws on import (a bad
      // import name, a top-level error) also turns every test red whatever the defect.
      // Library modules under src/ and test/ are imported in a child process; entry
      // points that act on import (src/cli.mjs, scripts/) are parse-checked only.
      // Test files (*.test.mjs) run their tests on import, so they are entry points too.
      const loadable = applied && parses && ((/^(src|test)\/.*\.m?js$/.test(control.file) && control.file !== 'src/cli.mjs' && !/\.test\.m?js$/.test(control.file)) || LOAD_SAFE_SCRIPTS.has(control.file));
      const loads = loadable ? spawnSync(process.execPath, ['--input-type=module', '-e', `await import(${JSON.stringify(pathToFileURL(path).href)})`], { cwd: dir, encoding: 'utf8', env: { ...process.env, CANON_LOOPBACK_ONLY: '1' } }).status === 0 : null;
      lap('mutate');
      check('mutation');
      lap('check');
      // The mutated run executes only the intended tests: the control needs nothing else to fail.
      const runBroken = Boolean(applied && parses && loads !== false && !vanished && base.intends.length);
      const { swept: brokenSwept = null, ...brokenRun } = runBroken ? await runTests(dir, control.tests, base.intends, mine.token) : {};
      const broken = runBroken ? brokenRun : null;
      mine.swept = brokenSwept;
      lap('mutated');
      check('mutated run');
      lap('check');
      // The intended assertions that failed. None means the control went red, if at all,
      // for some other reason, which never counts.
      const intendedFailed = broken ? base.intends.filter((name) => broken.failed.includes(name)) : [];
      // Exactly the intended tests ran, each once: a name pattern that matched nothing, another
      // test, or the same name in two files, is not the proof this control claims.
      const ranIntended = broken !== null && broken.ran.length === base.intends.length && [...broken.ran].sort().join('\n') === [...base.intends].sort().join('\n');
      result = {
        ...base,
        mutationApplied: applied,
        mutationParses: parses,
        mutationLoads: loads,
        baseline,
        ...(reusedFrom ? { baselineReusedFrom: reusedFrom } : {}),
        alone,
        ...(aloneFrom ? { aloneReusedFrom: aloneFrom } : {}),
        intendedAlone,
        broken,
        intendedFailed,
        ranIntended,
        wentRed: applied && parses && loads !== false && baseline.exitCode === 0 && broken !== null && broken.exitCode !== 0 && ranIntended && intendedFailed.length > 0 && intendedFailed.length === base.intends.length && !vanished,
        leftBehind: left,
        warnings,
      };
      // Red only if the intended tests pass alone before the mutation.
      if (!intendedAlone) result.wentRed = false;
    } catch (err) {
      check('run');
      result = { ...base, error: `control run failed: ${err.code ?? ''} ${err.message}`.trim(), wentRed: false, warnings };
      // A holder that was gone before its release: the group is unknown, and the whole run fails.
      if (err.code === 'EHOLDERLOST') runProblems.push(`${control.id}: ${err.message}`);
    }
    results[index] = result;
    try {
      if (beforeCleanup) await beforeCleanup(dir, control);
      check('cleanup');
      lap('check');
    } finally {
      // Mutated code can break a test's own cleanup (a serve process, a helper); stop whatever
      // the mutated run left from this control's copy or process groups before removing the copy.
      let real = null;
      try {
        real = realpathSync(dir);
      } catch {
        warnings.push(`scratch copy ${dir} was already gone before cleanup`);
      }
      if (real && !mine.dirs.includes(real)) mine.dirs.push(real);
      try {
        await sweep('mutated', mine.swept);
      } catch (err) {
        warnings.push(`the sweep for leftover processes failed: ${err.message}`);
      }
      // Only this control's own copy (created by prepare above) is ever removed.
      try {
        await rm(dir, { recursive: true, force: true });
      } catch (err) {
        warnings.push(`cleanup of ${dir} failed: ${err.code ?? err.message}`);
      }
      // A vanished copy or any warning at any phase: this control is not red.
      if (vanished) result.vanished = vanished;
      if (modified) result.modified = modified;
      if (modified) result.wentRed = false;
      if (vanished || warnings.length) result.wentRed = false;
      // The UNMUTATED tests must clean up after themselves, and nothing may survive being stopped.
      if (left.baseline || strays.length) result.wentRed = false;
      if (strays.length) result.strays = strays;
      if (exitingNotCounted.length) result.exitingNotCounted = exitingNotCounted;
      lap('cleanup');
      result.timings = timings;
    }
  };
  await pool(selected, size, runOne);
  // Run-end sweep: nothing this run started may outlive it. No process-group number is matched:
  // a number remembered from an earlier test run may belong to a stranger by now. What is PROVEN a
  // control's (its token, in its copy) is stopped; what only a path names is reported and counted
  // against the control whose copy it names, and never signalled; a path that names no control's
  // copy fails the run.
  const allDirs = owned.flatMap((o) => o.dirs);
  const byCwd = cwdStrays(allDirs, before);
  // A sweep that could not finish has shown nothing: every control of the run says so, and the run fails.
  if (!byCwd.complete) for (const r of results) if (r) r.sweepIncomplete = byCwd.why;
  const charge = (owner, stray) => {
    const result = results.find((r) => r?.id === owner.id);
    if (!result) return false;
    result.strays = [...(result.strays ?? []), { ...stray, phase: 'run end' }];
    result.wentRed = false;
    // The owner's unmutated runs were handed on before this stray was seen: whoever took one
    // rests on a run that did not clean up, and is not red either.
    for (const r of results) {
      if (!r || r === result || (r.baselineReusedFrom !== result.id && r.aloneReusedFrom !== result.id)) continue;
      r.reusedFromStrayOwner = result.id;
      r.wentRed = false;
    }
    return true;
  };
  const seen = new Set();
  const key = (p) => `${p.pid} ${p.start}`;
  const everyone = leftOutsideAll({ owners: owned.map((o) => ({ id: o.id, token: o.token, dirs: o.dirs })), before });
  for (const o of owned) {
    const outside = everyone.get(o.id);
    for (const p of await reap(outside.proven, o.token)) { seen.add(key(p)); charge(o, { ...p, stopped: false }); }
    for (const p of outside.proven) seen.add(key(p));
    for (const p of outside.reported) if (!seen.has(key(p))) { seen.add(key(p)); charge(o, { ...p, signalled: false, stopped: false }); }
  }
  for (const s of byCwd.found) {
    if (seen.has(key(s))) continue;
    seen.add(key(s));
    const owner = ownerByPath(s, owned);
    const stray = { ...s, why: 'its working directory is inside a copy of this run; not proven to be this run\'s', signalled: false, stopped: false };
    if (!owner || !charge(owner, stray)) runProblems.push(`a process (pid ${s.pid}, started ${s.start ?? 'unknown'}) has its working directory in a copy of this run that belongs to no control: it was NOT stopped, and no control is blamed`);
  }
  results.runProblems = runProblems;
  for (const off of unhook) off();
  return results;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const ids = process.argv.slice(2);
  let selected;
  try {
    selected = selectControls(ids);
    assertAnchored(selected);
  } catch (err) {
    if (!(err instanceof ControlSelectionError)) throw err;
    process.stderr.write(`red-controls: ${err.message}\n`);
    process.exit(2);
  }
  const results = await runControls(ids);
  process.stdout.write(`${JSON.stringify(results, null, 2)}\n`);
  for (const r of results) for (const w of r.warnings ?? []) process.stderr.write(`red-controls: ${r.id}: warning: ${w}\n`);
  for (const r of results) if (r.error) process.stderr.write(`red-controls: ${r.id}: ${r.error}\n`);
  // Every selected control must have a result, every result must be red, and no copy
  // may have vanished or left a warning.
  const verdict = runVerdict(results, selected.length);
  for (const p of verdict.problems) process.stderr.write(`red-controls: ${p}\n`);
  process.exit(verdict.ok ? 0 : 1);
}
